INSERT INTO g2p_crop_taxonomy_type (type_code, source_id, category_code, display_name, display_name_i18n, scientific_name, centre, image_url, description, source_reported_variety_count, status) VALUES
  ('adzuki-bean', 'croptype-259092633826', 'food-legume', 'Adzuki bean', NULL, 'Vigna angularis', 'MARC', 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/Adzuki bean.jpg', 'Adzuki bean (Phaseolus angularis) is an annual bushy widely grown in Japan and china for its seeds which are used as food and to produce a flour. The plant is erect, 0.3 to 0.6 meter high, although some gardeners have reported them to be indeterminate, growing and producing until frost.', 2, 'ACTIVE'),
