  ('avocado', 'croptype-928367285259', 'fruit-and-vegetables', 'Avocado', '{"am": "አቮካዶ"}'::jsonb, 'Persea americana M.', 'MARC', 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/Avocado.jpg', NULL, 6, 'ACTIVE'),
  ('banana', 'croptype-768903809650', 'fruit-and-vegetables', 'Banana', '{"am": "ሙዝ"}'::jsonb, 'Musa paradisiaca var. sapiertum', 'MARC', 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/Banana.jpg', NULL, 14, 'ACTIVE'),
  ('barley', 'croptype-315796933991', 'cereal', 'Barley', '{"am": "ገብስ"}'::jsonb, 'Hordeum vulgare', 'SiARC', 'http://196.191.93.34/moa-portal/cropopen/varieites/crops/Barley.jpg', NULL, 81, 'ACTIVE'),
